import re, json
text=open('/root/test.bib','r',encoding='utf-8').read()
entries=re.split(r'\n@', text)
res=[]
for i,e in enumerate(entries):
    if not e.strip():
        continue
    if i>0:
        e='@'+e
    m=re.search(r'title\s*=\s*[{\"](.+?)[}\"]\s*,\s*\n', e, re.S)
    if m:
        title=m.group(1).replace('\n',' ').strip()
    else:
        title=None
    mkey=re.match(r'@\w+\{([^,]+),', e)
    key=mkey.group(1) if mkey else None
    res.append((key,title))
print('\n'.join(f"{k}: {t}" for k,t in res))
